      aufgaben: [
        { art: "Verständnis", frage: `<p>Nenne die vier Ziele des magischen Vierecks mit je einer Messgröße und erläutere, warum man von „magisch“ spricht.</p>`, loesung: `<ul><li>Preisniveaustabilität – Inflationsrate (VPI/HVPI)</li><li>Hoher Beschäftigungsstand – Arbeitslosenquote</li><li>Außenwirtschaftliches Gleichgewicht – Außenbeitrag/Leistungsbilanzsaldo in % des BIP</li><li>Stetiges und angemessenes Wachstum – Veränderungsrate des realen BIP</li></ul><p>„Magisch“, weil zwischen den Zielen Konflikte bestehen und sie deshalb nicht alle gleichzeitig voll erreicht werden können.</p>` },
        { art: "Fall", frage: `<p>Die Bundesregierung will die Arbeitslosigkeit durch ein kreditfinanziertes Investitionsprogramm senken. Welche Zielbeziehungen sind betroffen? Beurteile kurz.</p>`, loesung: `<ul><li><strong>Harmonie</strong> Wachstum ↔ Beschäftigung: Mehr Nachfrage erhöht Produktion und Beschäftigung.</li><li><strong>Konflikt</strong> Beschäftigung ↔ Preisniveaustabilität: Zusätzliche Nachfrage kann bei ausgelasteten Kapazitäten die Preise treiben (Phillips-Kurve).</li><li><strong>Konflikt</strong> mit tragfähigen Staatsfinanzen (Achteck/Schuldenbremse): Die Staatsverschuldung steigt.</li><li>Möglicher Konflikt mit dem außenwirtschaftlichen Gleichgewicht: Mehr Nachfrage erhöht auch die Importe.</li></ul>` },
        { art: "Rechnung", frage: `<p>Prüfe die Zielerreichung mit folgenden Beispielwerten: VPI Vorjahr 120,0, aktuell 123,0; Erwerbstätige 44,6 Mio., Arbeitslose 2,8 Mio.; reales BIP Vorjahr 3.500 Mrd. €, aktuell 3.517,5 Mrd. €. Orientierungswerte: Inflation ≤ 2 %, Arbeitslosenquote ≤ 3 %, Wachstum ≥ 2 %.</p>`, loesung: `<div class="formel">Inflationsrate = (123,0 − 120,0) ÷ 120,0 × 100 = 2,5 % → verfehlt</div><div class="formel">Arbeitslosenquote = 2,8 ÷ (44,6 + 2,8) × 100 = 5,91 % → verfehlt</div><div class="formel">Wachstum = (3.517,5 − 3.500) ÷ 3.500 × 100 = 0,5 % → verfehlt</div><p>Alle drei Ziele werden verfehlt – eine Stagflationstendenz (schwaches Wachstum bei erhöhter Inflation).</p>` },
        { art: "Verständnis", frage: `<p>Erläutere die Aussage der modifizierten Phillips-Kurve und warum sie heute kritisch gesehen wird.</p>`, loesung: `<p>Aussage: Zwischen Inflationsrate und Arbeitslosenquote besteht ein negativer Zusammenhang – mehr Inflation ermöglicht weniger Arbeitslosigkeit (Zielkonflikt). Kritik: In den 1970er-Jahren traten hohe Inflation und hohe Arbeitslosigkeit gleichzeitig auf (Stagflation). Wirtschaftssubjekte passen ihre Inflationserwartungen an (Lohnforderungen), sodass dauerhaft höhere Inflation keine dauerhaft niedrigere Arbeitslosigkeit bringt (langfristig senkrechte Phillips-Kurve).</p>` }
      ],
      quiz: [
        { frage: "Welches Ziel ist im § 1 Stabilitätsgesetz NICHT genannt?", optionen: ["Stabilität des Preisniveaus", "Gerechte Einkommensverteilung", "Hoher Beschäftigungsstand", "Außenwirtschaftliches Gleichgewicht"], richtig: 1, erklaerung: "Gerechte Einkommens- und Vermögensverteilung ist eine Erweiterung zum magischen Sechseck." },
        { frage: "Wie wird das Wachstumsziel im StabG beschrieben?", optionen: ["maximales Wachstum", "Nullwachstum", "stetiges und angemessenes Wachstum", "Wachstum von mindestens 3 %"], richtig: 2, erklaerung: "Gesetzestext: „bei stetigem und angemessenem Wirtschaftswachstum“." },
        { frage: "Welche Zielbeziehung besteht in der Regel zwischen Wirtschaftswachstum und hohem Beschäftigungsstand?", optionen: ["Zielharmonie", "Zielkonflikt", "Zielneutralität", "Zielidentität"], richtig: 0, erklaerung: "Mehr Produktion braucht in der Regel mehr Arbeitskräfte – die Ziele fördern sich gegenseitig." },
        { frage: "Was stellt die modifizierte Phillips-Kurve dar?", optionen: ["Zusammenhang zwischen Zins und Investitionen", "Zusammenhang zwischen Wechselkurs und Exporten", "Zusammenhang zwischen Geldmenge und Preisniveau", "Zusammenhang zwischen Inflationsrate und Arbeitslosenquote"], richtig: 3, erklaerung: "Sie zeigt den (kurzfristigen) Zielkonflikt zwischen Preisniveaustabilität und Beschäftigung." },
        { frage: "Stagflation bezeichnet …", optionen: ["sinkende Preise bei hohem Wachstum", "wirtschaftliche Stagnation bei gleichzeitiger Inflation", "eine stabile Wirtschaft ohne Inflation", "eine Phase stark steigender Aktienkurse"], richtig: 1, erklaerung: "Stagnation + Inflation – widerspricht der einfachen Phillips-Kurve." }
      ],
      begriffe: [
        { b: "Stabilitätsgesetz (StabG)", d: "Gesetz von 1967, das Bund und Länder auf das gesamtwirtschaftliche Gleichgewicht verpflichtet (magisches Viereck)." },
        { b: "Magisches Viereck", d: "Die vier gleichrangigen Ziele des StabG, die wegen Zielkonflikten nicht gleichzeitig voll erreichbar sind." },
        { b: "Magisches Sechseck", d: "Erweiterung um gerechte Einkommens-/Vermögensverteilung und Schutz der natürlichen Lebensgrundlagen." },
        { b: "Zielkonflikt", d: "Die Förderung eines Ziels beeinträchtigt die Erreichung eines anderen Ziels." },
        { b: "Phillips-Kurve", d: "Darstellung des negativen Zusammenhangs zwischen Inflationsrate (ursprünglich Lohnsteigerung) und Arbeitslosenquote." },
        { b: "Stagflation", d: "Gleichzeitiges Auftreten von wirtschaftlicher Stagnation und Inflation." },
        { b: "Sachverständigenrat", d: "Unabhängiges Gremium („Wirtschaftsweise“), das jährlich ein Gutachten zur gesamtwirtschaftlichen Entwicklung erstellt." }
      ]
