        { frage: "Welche Maßnahme ist angebotsorientiert?", optionen: ["Senkung der Lohnnebenkosten", "Erhöhung des Kindergelds zur Konsumstärkung", "Deficit spending im Abschwung", "Kaufprämie für Elektroautos zur Nachfragestützung"], richtig: 0, erklaerung: "Geringere Lohnnebenkosten verbessern die Kostensituation der Unternehmen." },
        { frage: "Wie hoch darf die strukturelle Neuverschuldung des Bundes laut Schuldenbremse maximal sein?", optionen: ["3 % des BIP", "0,35 % des BIP", "60 % des BIP", "0 % des BIP"], richtig: 1, erklaerung: "Art. 115 GG: 0,35 % des BIP; 3 % und 60 % sind die EU-Kriterien." }
